def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    try:
        # Basic validation: ensure the object has the expected attributes of a timedelta
        if not (hasattr(value, "days") and hasattr(value, "seconds") and hasattr(value, "microseconds")):
            raise TypeError("Expected a datetime.timedelta instance")
        # Return a serializable representation
        return {
            "days": value.days,
            "seconds": value.seconds,
            "microseconds": value.microseconds,
        }
    except Exception as exc:
        # Wrap any unexpected error in a ValueError for clarity
        raise ValueError(f"Failed to dehydrate timedelta: {exc}") from exc

def dehydrate_time(value):
    """
    Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: A string representation of the time suitable for serialization.
    """
    # Allow None to be passed through unchanged
    if value is None:
        return None

    # Ensure the value has an isoformat method (common to datetime.time)
    if not hasattr(value, "isoformat") or not callable(value.isoformat):
        raise TypeError(f"Expected a time-like object, got {type(value).__name__}")

    # Reject datetime.datetime objects which also have isoformat but include a date
    if hasattr(value, "year"):
        raise TypeError(f"Expected a time object, got datetime.datetime")

    try:
        # Use isoformat to get a standard string representation
        return value.isoformat()
    except Exception as exc:
        raise ValueError(f"Could not dehydrate time value: {exc}") from exc

