    :return: dict with 'x' and 'y' keys representing the point
    """
    try:
        if value is None:
            raise TypeError("value cannot be None")
        # Ensure the object has the expected attributes
        if not hasattr(value, "x") or not hasattr(value, "y"):
            raise TypeError("value must have 'x' and 'y' attributes")
        x = getattr(value, "x")
