def round_half_to_even(n):
    """
    Round a number to the nearest integer using the "round half to even" rule.
    For .5 fractions, round to the nearest even integer.
    Handles positive and negative numbers.
    Raises TypeError for non-numeric input and ValueError for NaN or infinite values.
    """
    # Validate input type
    if not isinstance(n, (int, float)):
        raise TypeError(f"Input must be an int or float, got {type(n).__name__}")
    # Handle NaN and infinities
    if isinstance(n, float):
        if n != n:  # NaN check
            raise ValueError("Cannot round NaN")
        if n == float('inf') or n == float('-inf'):
            raise ValueError("Cannot round infinite values")
    # If already an integer, return as int
    if isinstance(n, int):
        return n
    # Custom floor implementation without importing math
    def custom_floor(x):
        if x >= 0:
            return int(x)
        else:
            return int(x) - 1 if x != int(x) else int(x)
    floor_val = custom_floor(n)
    diff = n - floor_val
    # Compare diff with 0.5 using a tolerance to avoid floating point issues
    eps = 1e-12
    if diff < 0.5 - eps:
        return floor_val
    elif diff > 0.5 + eps:
        return floor_val + 1
    else:  # diff is approximately 0.5
        if floor_val % 2 == 0:
            return floor_val
        else:
            return floor_val + 1

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import os
    import sys
    import subprocess
    from concurrent.futures import ThreadPoolExecutor, as_completed

    # Validate inputs
    if not isinstance(cmd, tuple) or not all(isinstance(c, str) for c in cmd):
        raise TypeError("cmd must be a tuple of strings")
    if not isinstance(varargs, Sequence):
        raise TypeError("varargs must be a sequence of strings")
    if not isinstance(target_concurrency, int) or target_concurrency <= 0:
        raise ValueError("target_concurrency must be a positive integer")
    if not isinstance(_max_length, int) or _max_length <= 0:
        raise ValueError("max_length must be a positive integer")

    # Helper to partition arguments respecting max length
    def partition_args(args: Sequence[str], max_len: int) -> list[list[str]]:
        partitions: list[list[str]] = []
        current: list[str] = []
        current_len = 0
        for arg in args:
            # Estimate length: argument length + 1 for space
            arg_len = len(arg) + 1
            if current_len + arg_len > max_len and current:
                partitions.append(current)
                current = [arg]
                current_len = arg_len
            else:
                current.append(arg)
                current_len += arg_len
        if current:
            partitions.append(current)
        return partitions

    # Determine if we should use a pty
    use_pty = False
    if color:
        try:
            # Only use pty on POSIX systems where sys.stdout is a tty
            if os.name != "nt" and sys.stdout.isatty():
                use_pty = True
        except Exception:
            use_pty = False

    # Function to run a single command partition
    def run_partition(part: list[str]) -> tuple[int, bytes]:
        full_cmd = list(cmd) + part
        try:
            if use_pty:
                # Allocate a pseudo-terminal
                master_fd, slave_fd = os.openpty()
                proc = subprocess.Popen(
                    full_cmd,
                    stdout=slave_fd,
                    stderr=slave_fd,
                    **kwargs,
                )
                os.close(slave_fd)
                output = os.read(master_fd, 1024 * 1024)
                os.close(master_fd)
                return proc.wait(), output
            else:
                result = subprocess.run(full_cmd, capture_output=True, **kwargs)
                return result.returncode, result.stdout
        except Exception as e:
            # In case of error, return non-zero code and error message
            return 1, str(e).encode()

    # If no varargs, just run the command once
    if not varargs:
        return run_partition([])

    # Partition arguments
    partitions = partition_args(varargs, _max_length)

    # Run partitions concurrently
    exit_code = 0
    combined_output = bytearray()
    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        futures = {executor.submit(run_partition, part): part for part in partitions}
        for future in as_completed(futures):
            code, out = future.result()
            combined_output.extend(out)
            if code != 0 and exit_code == 0:
                exit_code = code

