    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        self[key] = default
        return default
    except TypeError as exc:
        raise ValueError(f"Invalid key {key!r}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error setting default for key {key!r}: {exc}") from exc

def get(self, key, default=None):
