def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
        """Return attribute names and descriptions defined by interface."""
        # Validate the 'all' argument
        if not isinstance(all, bool):
            raise TypeError(f"'all' must be a boolean, got {type(all).__name__}")

        try:
            # Determine which classes to inspect
            classes = self.__class__.__mro__ if all else (self.__class__,)

            # Use an ordered dict-like approach to avoid duplicates while preserving order
            names_desc = {}

            for cls in classes:
                # Skip the base 'object' class
                if cls is object:
                    continue

                # Handle annotations (type hints) which may not have a value in __dict__
                annotations = getattr(cls, "__annotations__", {})
                for name in annotations:
                    if name in names_desc or name.startswith("_"):
                        continue
                    description = None
                    if name in cls.__dict__:
                        value = cls.__dict__[name]
                        description = getattr(value, "__doc__", None)
                    if description is None:
                        desc_dict = getattr(cls, "__descriptions__", {})
                        description = desc_dict.get(name)
                    names_desc[name] = description

                # Handle attributes defined directly in the class dict
                for name, value in cls.__dict__.items():
                    if name in names_desc or name.startswith("_"):
                        continue
                    description = getattr(value, "__doc__", None)
                    if description is None:
                        desc_dict = getattr(cls, "__descriptions__", {})
                        description = desc_dict.get(name)
                    names_desc[name] = description

            # Return a list of (name, description) tuples
            return list(names_desc.items())

        except Exception as exc:
            # Wrap any unexpected exception in a RuntimeError with context
            raise RuntimeError(f"Failed to retrieve names and descriptions: {exc}") from exc

