def to_csv(self, separator=",", header=None):
        """
        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        # Validate separator
        if not isinstance(separator, str):
            raise TypeError("separator must be a string")
        # Validate header
        if header is not None and not isinstance(header, str):
            raise TypeError("header must be a string or None")

        lines = []
        if header is not None:
            lines.append(header)

        # Retrieve points; raise a clear error if not present
        try:
            points = self.points
        except AttributeError as exc:
            raise AttributeError("The object has no 'points' attribute") from exc

        # Ensure points is iterable
        try:
            iterator = iter(points)
        except TypeError as exc:
            raise TypeError("self.points must be an iterable of points") from exc

        for point in iterator:
            # Expect point to be a tuple (coordinate, value)
            if isinstance(point, tuple) and len(point) == 2:
                coord, value = point
            else:
                # If point is not a 2-tuple, try to unpack it
                try:
                    coord, value = point[0], point[1]
                except Exception:
                    # Skip malformed point
                    continue

            # Convert coordinate to string parts
            if isinstance(coord, (list, tuple)):
                coord_parts = [str(c) for c in coord]
            else:
                coord_parts = [str(coord)]

            # Convert value to string parts
            if isinstance(value, str):
                value_parts = [value]
            elif isinstance(value, (list, tuple)):
                value_parts = [str(v) for v in value]
            elif value is None:
                value_parts = []
            else:
                value_parts = [str(value)]

            line = separator.join(coord_parts + value_parts)
            lines.append(line)

        return "\n".join(lines) if lines else ""

