def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to lists to allow indexing
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable")

    # Basic validation of lengths
    if len(edges_list) != len(bins_list) + 1:
        raise ValueError(
            f"Number of edges ({len(edges_list)}) must be one more than number of bins ({len(bins_list)})"
        )

    # Compute integral as sum of bin values times bin widths
    total = 0.0
    for i, bin_val in enumerate(bins_list):
        try:
            left_edge = float(edges_list[i])
            right_edge = float(edges_list[i + 1])
            width = right_edge - left_edge
            total += float(bin_val) * width
        except Exception as exc:
            raise ValueError(
                f"Invalid bin or edge at index {i}: {exc}"
            ) from exc

    return total

