    try:
        weight = float(weight)
    except Exception:
        return
    # Find bin indices for each dimension
    indices = []
    for dim, val in enumerate(coord):
        edges_dim = self.edges[dim]
        # Find the bin index where edges_dim[i] <= val < edges_dim[i+1]
        idx = None
        # Simple linear search; for large histograms consider binary search
        for i in range(len(edges_dim) - 1):
            if edges_dim[i] <= val < edges_dim[i + 1]:
                idx = i
                break
        if idx is None:
            # Coordinate is outside the histogram edges
            return
        indices.append(idx)
    # Increment the bin count
    try:
        self.bins[tuple(indices)] += weight
    except Exception:
        # If indexing fails (e.g., wrong shape), ignore silently
