def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        # Basic type check
        if not isinstance(inventory, dict):
            raise TypeError("Inventory must be a dictionary.")

        # Determine spec version
        spec_version = self.spec_version
        if extract_spec_version:
            type_val = inventory.get("type")
            if type_val:
                # Simple mapping from type to spec version
                type_to_version = {"v1": "1.0", "v2": "2.0", "1.0": "1.0", "2.0": "2.0"}
                spec_version = type_to_version.get(type_val, spec_version)

        # Required top‑level keys
        required_keys = ["name", "items"]
        for key in required_keys:
            if key not in inventory:
                raise ValueError(f"Missing required key '{key}' in inventory.")

        # Validate name
        if not isinstance(inventory["name"], str):
            raise TypeError("Inventory 'name' must be a string.")

        # Validate items list
        if not isinstance(inventory["items"], list):
            raise TypeError("Inventory 'items' must be a list.")
        for idx, item in enumerate(inventory["items"]):
            if not isinstance(item, dict):
                raise TypeError(f"Item at index {idx} must be a dict.")
            # Each item must have id and quantity
            for field in ("id", "quantity"):
                if field not in item:
                    raise ValueError(f"Item at index {idx} missing '{field}'.")
                if not isinstance(item[field], int):
                    raise TypeError(f"Item '{field}' at index {idx} must be an integer.")

        # Spec‑specific checks
        if spec_version == "1.0":
            # In spec 1.0, each item must have a numeric price
            for idx, item in enumerate(inventory["items"]):
                if "price" not in item:
                    raise ValueError(f"Item at index {idx} missing 'price' for spec 1.0.")
                if not isinstance(item["price"], (int, float)):
                    raise TypeError(f"Item 'price' at index {idx} must be numeric.")
        elif spec_version == "2.0":
            # In spec 2.0, inventory must have a location string
            if "location" not in inventory:
                raise ValueError("Inventory missing 'location' for spec 2.0.")
            if not isinstance(inventory["location"], str):
                raise TypeError("Inventory 'location' must be a string.")

        # All checks passed
        return True

    except Exception as exc:
        raise ValueError(f"Inventory validation failed: {exc}") from exc

