def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if inventory is None:
        raise TypeError("inventory cannot be None")
    if version is None:
        raise ValueError("version cannot be None")

    # Determine the list of version entries
    if isinstance(inventory, dict):
        if "versions" in inventory:
            versions = inventory["versions"]
        elif "files" in inventory:
            # Treat as a single version
            versions = [inventory]
        else:
            raise TypeError(
                "inventory dict must contain either 'versions' or 'files' keys"
            )
    elif isinstance(inventory, list):
        versions = inventory
    else:
        raise TypeError("inventory must be a dict or a list")

    # Find the index of the requested version
    target_index = None
    for idx, v in enumerate(versions):
        # v can be a dict with various possible keys for the version identifier
        if isinstance(v, dict):
            # Common keys that might hold the version identifier
            for key in ("name", "id", "version"):
                if key in v and v[key] == version:
                    target_index = idx
                    break
            if target_index is not None:
                break
        else:
            # If the version entry itself is a simple value (e.g., a string)
            if v == version:
                target_index = idx
                break

    if target_index is None:
        raise ValueError(f"Version {version!r} not found in inventory")

    # Build the mapping from logical path to a set of content files
    logical_path_map = {}
    for v in versions[target_index:]:
        # Each version entry should contain a 'files' mapping
        files = None
        if isinstance(v, dict):
            files = v.get("files")
        if not isinstance(files, dict):
            continue  # Skip entries that don't have a proper files mapping

        for logical_path, content_file in files.items():
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(content_file)

    return logical_path_map

