def render(pieces, style):
    """Render the given version pieces into the requested style."""
    try:
        if pieces is None:
            return ""
        # Ensure pieces is iterable
        try:
            iter(pieces)
        except TypeError:
            raise TypeError("pieces must be an iterable of strings or numbers")
        # Convert each piece to string
        str_pieces = []
        for p in pieces:
            if isinstance(p, (int, float)):
                str_pieces.append(str(p))
            elif isinstance(p, str):
                str_pieces.append(p)
            else:
                try:
                    str_pieces.append(str(p))
                except Exception:
                    raise TypeError(f"piece {p!r} cannot be converted to string")
        # Determine separator based on style
        if style is None:
            style = "dot"
        if not isinstance(style, str):
            raise TypeError("style must be a string")
        style = style.lower()
        if style == "dot":
            sep = "."
        elif style == "dash":
            sep = "-"
        elif style == "underscore":
            sep = "_"
        elif style == "none":
            sep = ""
        else:
            raise ValueError(f"Unsupported style: {style!r}")
        return sep.join(str_pieces)
    except Exception as e:
        if isinstance(e, (TypeError, ValueError)):
            raise
        raise RuntimeError(f"Error rendering version pieces: {e}") from e

