def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Validate inputs
    if not isinstance(vcs, str):
        raise TypeError(f"vcs must be a string, got {type(vcs).__name__}")
    if not isinstance(method, str):
        raise TypeError(f"method must be a string, got {type(method).__name__}")

    # Ensure a registry exists on the function object
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}

    def decorator(func):
        if not callable(func):
            raise TypeError(f"decorated object must be callable, got {type(func).__name__}")
        # Register the function under the (vcs, method) key
        register_vcs_handler._registry[(vcs, method)] = func
        return func

    return decorator

