                            print(f"Warning: Object {obj} failed validation.")
                else:
                    # If no validation method, consider it invalid
                    is_good = False
                    if show_warnings:
                        print(f"Warning: Object {obj} has no 'is_valid' method.")
            except Exception as exc:
                is_good = False
                if show_warnings:
                    print(f"Warning: Exception during validation of {obj}: {exc}")

        # Check the object's digest if requested
        if check_digests and is_good:
            try:
                if hasattr(obj, "check_digest"):
                    if not obj.check_digest():
                        is_good = False
                        if show_warnings:
                            print(f"Warning: Object {obj} failed digest check.")
                else:
                    if show_warnings:
                        print(f"Warning: Object {obj} has no 'check_digest' method.")
            except Exception as exc:
                is_good = False
                if show_warnings:
                    print(f"Warning: Exception during digest check of {obj}: {exc}")

        if is_good:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
        """Create and initialize a new OCFL storage root."""
        # Validate the root path
        if not hasattr(self, "root_path") or not isinstance(self.root_path, str) or not self.root_path:
            raise ValueError("`root_path` must be a non-empty string attribute of the instance.")
        # Ensure the OCFL version is set, default to "1.0" if missing
        ocfl_version = getattr(self, "ocfl_version", "1.0")
        if not isinstance(ocfl_version, str) or not ocfl_version:
            ocfl_version = "1.0"
        # Check if the root already exists
        if os.path.exists(self.root_path):
            raise FileExistsError(f"The root path '{self.root_path}' already exists.")
        try:
            # Create the root directory
            os.makedirs(self.root_path, exist_ok=False)
            # Create standard OCFL subdirectories
            subdirs = ["objects", "versions", "metadata"]
            for sub in subdirs:
                os.makedirs(os.path.join(self.root_path, sub), exist_ok=False)
            # Create an initial manifest file
            manifest_path = os.path.join(self.root_path, "manifest.json")
            manifest_data = {
                "ocfl_version": ocfl_version,
                "objects": []
            }
            with open(manifest_path, "w", encoding="utf-8") as mf:
                json.dump(manifest_data, mf, indent=2)
            # Create a config file with root-level metadata
            config_path = os.path.join(self.root_path, "config.json")
            config_data = {
                "ocfl_version": ocfl_version,
                "created_at": datetime.utcnow().isoformat() + "Z"
            }
            with open(config_path, "w", encoding="utf-8") as cf:
                json.dump(config_data, cf, indent=2)
        except Exception as exc:
            # Clean up partially created directories if an error occurs
            if os.path.isdir(self.root_path):
                try:
                    shutil.rmtree(self.root_path)
                except Exception:
                    pass
            raise RuntimeError(f"Failed to initialize OCFL root at '{self.root_path}': {exc}") from exc
        # Initialization successful; no return value needed.

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise ValueError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    # Ensure we have a root inventory to compare against
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise RuntimeError("root_inventory attribute is missing or not a dict")

    # Ensure we have a base path to locate version directories
    if not hasattr(self, "base_path") or not isinstance(self.base_path, str):
        raise RuntimeError("base_path attribute is missing or not a string")

    # Prepare a structure to hold differences
    self.different_digests = {}

    for idx, ver_dir in enumerate(version_dirs, start=1):
        # Construct the path to the inventory file
        inv_path = os.path.join(self.base_path, ver_dir, "inventory.json")

        # Check that the inventory file exists
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing for version '{ver_dir}' at expected path: {inv_path}")

        # Load the inventory
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv_data = json.load(f)
        except (OSError, json.JSONDecodeError) as e:
            raise RuntimeError(f"Failed to read or parse inventory for version '{ver_dir}': {e}")

        if not isinstance(inv_data, dict):
            raise RuntimeError(f"Inventory for version '{ver_dir}' is not a dict as expected")

        # Compare each content digest with the root inventory
        for path, inv_digest in inv_data.items():
            root_digest = self.root_inventory.get(path)
            if root_digest is None:
                # New content not present in root; treat as difference
                diff_key = path
                self.different_digests.setdefault(diff_key, []).append(
                    (ver_dir, inv_digest, None)
                )
            elif inv_digest != root_digest:
                diff_key = path
                self.different_digests.setdefault(diff_key, []).append(
                    (ver_dir, inv_digest, root_digest)
                )

        # Optionally, check for content present in root but missing in this inventory
        # (not required by the docstring but useful for completeness)
        for path in self.root_inventory:
            if path not in inv_data:
                diff_key = path
                self.different_digests.setdefault(diff_key, []).append(
                    (ver_dir, None, self.root_inventory[path])
                )

    # Return the collected differences for external inspection if needed
    return self.different_digests

