def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("dicts must be an iterable of dictionaries")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for k, v in d.items():
            if not isinstance(v, (int, float)):
                raise TypeError(f"Value for key {k!r} must be numeric, got {type(v).__name__}")
            result[k] = result.get(k, 0) + v
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Define common textual representations of None
    none_reprs = {"none", "null", "nil", "na", "n/a"}
    try:
        # Only strings can represent a textual None
        if not isinstance(val, str):
            return False
        # Normalize: strip whitespace and convert to lowercase
        normalized = val.strip().lower()
        return normalized in none_reprs
    except Exception:
        # In case of unexpected errors, return False
        return False

