def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate number
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non-negative")

    # Validate alphabet
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if len(alphabet) == 0:
        raise ValueError("alphabet must not be empty")
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str):
            raise TypeError(f"alphabet element at index {idx} must be a string")
        if len(ch) == 0:
            raise ValueError(f"alphabet element at index {idx} must not be empty")

    base = len(alphabet)

    # Validate padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Convert number to base `base` using the alphabet
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits.reverse()

    result = ''.join(digits)

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
