    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    result = set()

    def _collect(c):
        try:
            for sub in c.__subclasses__():
                if sub not in result:
                    result.add(sub)
                    _collect(sub)
        except Exception:
            # If a subclass cannot be inspected, skip it
            pass

    _collect(cls)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    # Build mapping from symbol to its value
    mapping = {}
    for idx, symbol in enumerate(alphabet):
        if not isinstance(symbol, str):
            raise TypeError(f"alphabet element at index {idx} is not a string")
        if symbol in mapping:
            raise ValueError(f"duplicate symbol '{symbol}' in alphabet")
        mapping[symbol] = idx

    # Handle empty string
    if string == "":
        return 0

    # Convert string to integer
    result = 0
    for pos, char in enumerate(string):
        if char not in mapping:
            raise ValueError(f"character '{char}' at position {pos} not found in alphabet")
        result = result * base + mapping[char]
    return result

def unquote(name):
    """Remove quote from the given name."""
    # Validate input
    if name is None:
        return None
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    try:
        # Remove leading or trailing single or double quotes
        return re.sub(r"^['\"]|['\"]$", "", name)
    except Exception as e:
        # In case of unexpected regex errors, re-raise with context
        raise RuntimeError(f"Failed to unquote name '{name}': {e}") from e

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host or not isinstance(host, str):
        return False
    host = host.strip()
    if host.lower() == "localhost":
        return True
    # Direct loopback addresses
    if host in ("127.0.0.1", "::1"):
        return True
    try:
        # Gather local addresses from the current machine
        local_addrs = set()
        for info in socket.getaddrinfo(socket.gethostname(), None):
            local_addrs.add(info[4][0])
        # Include standard loopback addresses
        local_addrs.update(("127.0.0.1", "::1"))
        # Resolve the provided host
        for info in socket.getaddrinfo(host, None):
            addr = info[4][0]
            if addr in local_addrs:
                return True
    except socket.gaierror:
        # Host could not be resolved
        return False
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise ValueError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise ValueError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    # Check for existing file
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")

    # Ensure parent directories exist
    parent_dir = os.path.dirname(os.path.abspath(config_filename))
    if parent_dir and not os.path.isdir(parent_dir):
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError as e:
            raise RuntimeError(f"Failed to create directories '{parent_dir}': {e}") from e

    # Write the configuration file
    try:
        with open(config_filename, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        # Set the file mode
        os.chmod(config_filename, mode)
    except OSError as e:
        raise RuntimeError(f"Failed to write configuration to '{config_filename}': {e}") from e
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Helper to raise a consistent error
    def _raise(name):
        raise ValueError(f"Environment variable '{name}' not set and no default provided.")

    # Determine name and default based on matcher type
    if matcher is None:
        raise TypeError("Matcher cannot be None")

    # If matcher is a sequence (list/tuple) with 1 or 2 elements
    if isinstance(matcher, (list, tuple)):
        if not matcher:
            raise ValueError("Matcher sequence cannot be empty")
        name = matcher[0]
        if not isinstance(name, str):
            raise TypeError(f"Environment variable name must be a string, got {type(name).__name__}")
        default = matcher[1] if len(matcher) > 1 else None
        if len(matcher) > 2:
            raise ValueError("Matcher sequence can have at most two elements: name and optional default")
    # If matcher is a string, split on first colon
    elif isinstance(matcher, str):
        if not matcher:
            raise ValueError("Matcher string cannot be empty")
        parts = matcher.split(":", 1)
        name = parts[0]
        default = parts[1] if len(parts) == 2 else None
    else:
        raise TypeError(f"Matcher must be a string or a sequence of up to two elements, got {type(matcher).__name__}")

    # Retrieve from environment
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        _raise(name)
    return value

def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        # If target is already an ipaddress object, check its type directly
        if isinstance(target, (ipaddress.IPv4Address, ipaddress.IPv6Address)):
            return isinstance(target, ipaddress.IPv4Address)
        # If target is a string or bytes, attempt to parse it
        if isinstance(target, (str, bytes)):
            addr = ipaddress.ip_address(target)
            return isinstance(addr, ipaddress.IPv4Address)
        # For any other type, consider it not an IPv4 address
        return False
    except Exception:
        # Any parsing error or unexpected exception means it's not a valid IPv4 address
        return False

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if not isinstance(shape, (tuple, list)):
        raise TypeError(f"shape must be a tuple or list, got {type(shape).__name__}")
    try:
        shape_tuple = tuple(int(dim) for dim in shape)
    except Exception as e:
        raise ValueError(f"All dimensions in shape must be integers: {e}") from e
    if any(dim < 0 for dim in shape_tuple):
        raise ValueError("All dimensions in shape must be non-negative")

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as e:
        raise TypeError(f"Invalid dtype: {dtype}") from e

    # Create array
    try:
        return np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as e:
        raise RuntimeError(f"Failed to create array with shape {shape_tuple} and dtype {dtype_obj}") from e

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, logging, re
    if not hasattr(config_filenames, '__iter__'):
        raise TypeError('config_filenames must be an iterable of filenames')
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError('overrides must be a dict or None')
    configs = {}
    errors = []
    logger_name = 'config_loader'
    env_pattern = re.compile(r'\$\{([^}]+)\}')
    def _resolve_env(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value
    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if not isinstance(data, dict):
                raise ValueError('Configuration must be a JSON object')
            if resolve_env:
                data = _resolve_env(data)
            if overrides:
                data.update(overrides)
            configs[fname] = data
        except FileNotFoundError as e:
            record = logging.LogRecord(logger_name, logging.ERROR,
                                       fname, 0,
                                       f'File not found: {fname}', (), e)
            errors.append(record)
        except json.JSONDecodeError as e:
            record = logging.LogRecord(logger_name, logging.ERROR,
                                       fname, e.lineno,
                                       f'JSON decode error: {e.msg}', (), e)
            errors.append(record)
        except Exception as e:
            record = logging.LogRecord(logger_name, logging.ERROR,
                                       fname, 0,
                                       f'Error loading configuration: {e}', (), e)
            errors.append(record)
    return configs, errors

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as exc:
            raise ValueError(f"Could not encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Validate the protocol_version argument
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")

    # Retrieve the mapping of handlers; raise a clear error if missing
    try:
        handlers = cls._handlers
    except AttributeError as exc:
        raise RuntimeError(f"Class {cls.__name__} has no _handlers attribute") from exc

    # If no specific version requested, return a copy of all handlers
    if protocol_version is None:
        return dict(handlers)

    # Return a single-item dict if the requested version is supported,
    # otherwise return an empty dict
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

