def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        # The least recently used item is stored at the tail of the linked list.
        if not hasattr(self, "_tail") or self._tail is None:
            raise KeyError("popitem(): dictionary is empty")

        node = self._tail
        key, value = node.key, node.value

        # Remove the node from the doubly‑linked list.
        prev_node = node.prev
        if prev_node:
            prev_node.next = None
        else:
            # The list had only one node.
            self._head = None
        self._tail = prev_node

        # Remove the key from the cache dictionary.
        if hasattr(self, "_cache") and key in self._cache:
            del self._cache[key]
        else:
            # Inconsistent state – the key is missing from the cache.
            raise KeyError(f"Key {key!r} not found in cache during popitem")

        return key, value
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError to avoid leaking internal state.
        raise RuntimeError(f"Error in popitem: {exc}") from exc

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Try to use the built‑in popitem of the underlying mapping (dict or OrderedDict)
    try:
        return super().popitem()
    except AttributeError:
        # Fallback to common attribute names that may hold the mapping
        for attr in ("_data", "data", "_cache", "cache"):
            if hasattr(self, attr):
                container = getattr(self, attr)
                try:
                    return container.popitem()
                except Exception:
                    continue
    # If no suitable container was found, raise an informative error
    raise AttributeError("No suitable container found for popitem")

def identify_request(request: RequestType):
    """
    Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Helper to check truthiness of a value
        def _is_truthy(val):
            return bool(val)

        # 1. Check for a public message
        public = getattr(request, "public", None)
        if _is_truthy(public):
            return True

        # 2. Check for a private message
        private = getattr(request, "private", None)
        if _is_truthy(private):
            return True

        # 3. Check for a legacy payload indicator
        legacy = getattr(request, "legacy", None)
        if _is_truthy(legacy):
            return True

        # 4. If the request is a mapping (e.g., dict), perform the same checks
        if isinstance(request, dict):
            if _is_truthy(request.get("public")):
                return True
            if _is_truthy(request.get("private")):
                return True
            if _is_truthy(request.get("legacy")):
                return True

        # 5. Fallback: look for a type field that explicitly names Diaspora
        req_type = getattr(request, "type", None)
        if req_type == "diaspora":
            return True
        if isinstance(request, dict) and request.get("type") == "diaspora":
            return True

        return False
    except Exception:
        # In case of any unexpected error, conservatively return False
        return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        # Tag must be non-empty and at most 30 characters
        if not tag or len(tag) > 30:
            return False
        # Allowed characters: lowercase letters, digits, and hyphens
        # No leading/trailing hyphens, no consecutive hyphens
        import re
        pattern = r'^[a-z0-9]+(?:-[a-z0-9]+)*$'
        return re.match(pattern, tag) is not None
    except Exception:
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise TypeError("node cannot be None")
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an XML element-like object") from exc
    result = {}
    for child in children:
        result[child.tag] = child
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")

    # Try JSON first
    try:
        import json
        data = json.loads(document)
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        links = data.get("links", [])
        if not isinstance(aliases, list) or not isinstance(links, list):
            raise ValueError("Invalid JSON structure: 'aliases' and 'links' must be lists")
        return {"subject": subject, "aliases": aliases, "links": links}
    except json.JSONDecodeError:
        # Fall back to XRD (XML)
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)

            # Helper to ignore namespaces
            def _strip_ns(tag: str) -> str:
                return tag.split("}", 1)[-1] if "}" in tag else tag

            # Find subject
            subject_elem = root.find(".//{*}Subject")
            subject = subject_elem.text if subject_elem is not None else None

            # Find aliases
            aliases = [e.text for e in root.findall(".//{*}Alias") if e.text]

            # Find links
            links = []
            for link_elem in root.findall(".//{*}Link"):
                link = {}
                # Include all attributes
                for attr_name, attr_value in link_elem.attrib.items():
                    link[attr_name] = attr_value
                # If the link element contains child elements, include them as well
                for child in link_elem:
                    tag = _strip_ns(child.tag)
                    if child.text:
                        link[tag] = child.text
                links.append(link)

            return {"subject": subject, "aliases": aliases, "links": links}
        except ET.ParseError as e:
            raise ValueError(f"Document is neither valid JSON nor valid XRD XML: {e}") from e
        except Exception as e:
            raise ValueError(f"Unexpected error parsing XRD: {e}") from e
    except Exception as e:
        raise ValueError(f"Unexpected error parsing webfinger: {e}") from e

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Basic validation of the handle
    if not isinstance(handle, str):
        return {}
    # Strip any leading 'acct:' scheme
    if handle.lower().startswith('acct:'):
        handle = handle[5:]
    # Ensure the handle contains an '@' separating local part and domain
    if '@' not in handle:
        return {}
    local_part, domain = handle.split('@', 1)
    if not local_part or not domain:
        return {}
    # Construct the WebFinger URL
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
    try:
        import urllib.request
        import urllib.error
        import json
        # Prepare the request with a JSON accept header
        req = urllib.request.Request(url, headers={'Accept': 'application/json'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            # Check for a successful HTTP status
            if resp.getcode() != 200:
                return {}
            # Read and decode the response body
            raw = resp.read()
            try:
                data = raw.decode('utf-8')
            except Exception:
                # If decoding fails, return empty dict
                return {}
            # Parse JSON
            try:
                return json.loads(data)
            except json.JSONDecodeError:
                return {}
    except (urllib.error.URLError, urllib.error.HTTPError, ValueError):
        # Any network or URL related error results in an empty dict
        return {}
    except Exception:
        # Catch-all for any unforeseen errors
        return {}

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Validate input
    if not isinstance(host, str) or not host.strip():
        raise ValueError("host must be a non-empty string")

    # Ensure the host URL has a scheme
    host = host.strip()
    if not host.startswith(("http://", "https://")):
        url = f"https://{host}/.well-known/host-meta"
    else:
        # Remove any trailing slash and append the well-known path
        url = host.rstrip("/") + "/.well-known/host-meta"

    # Import required modules locally to avoid top-level imports
    import urllib.request
    import urllib.error
    import xml.etree.ElementTree as ET

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                raise RuntimeError(f"Failed to retrieve host-meta: HTTP {response.status}")
            raw_data = response.read()
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Could not retrieve host-meta from {url}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error while fetching host-meta from {url}: {exc}") from exc

    try:
        xml_text = raw_data.decode("utf-8")
    except Exception as exc:
        raise RuntimeError(f"Failed to decode host-meta response: {exc}") from exc

    # Validate that the response is well-formed XML
    try:
        ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise RuntimeError(f"Invalid XML in host-meta: {exc}") from exc

    # Return an XRD instance (assumes XRD is defined elsewhere in the package)
    return XRD(xml_text)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    import requests
    # Basic validation
    if not isinstance(url, str) or not url:
        return None, ValueError("url must be a non-empty string")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        return None, ValueError("timeout must be a positive number")
    if not isinstance(method, str) or not method:
        return None, ValueError("method must be a non-empty string")

    # Resolve the request method
    method_lower = method.lower()
    try:
        request_func = getattr(requests, method_lower)
    except AttributeError:
        return None, ValueError(f"Unsupported HTTP method: {method}")

    # Prepare request arguments
    request_kwargs = {
        "url": url,
        "timeout": timeout,
        "data": data,
    }
    # Merge any additional args/kwargs
    request_kwargs.update(kwargs)

    try:
        response = request_func(**request_kwargs)
        return response.status_code, None
    except requests.exceptions.RequestException as exc:
        # Return the exception instance for debugging
        return None, exc
    except Exception as exc:
        # Catch any other unexpected errors
        return None, exc

@classmethod
def workspace_manager(cls):
    """Gets the workspace manager."""
    try:
        if not hasattr(cls, "_workspace_manager"):
            # Define a simple WorkspaceManager class
            class WorkspaceManager:
                def __init__(self):
                    self.workspaces = {}

                def add_workspace(self, name, data):
                    if not isinstance(name, str):
                        raise ValueError("Workspace name must be a string")
                    self.workspaces[name] = data

                def get_workspace(self, name):
                    return self.workspaces.get(name)

                def list_workspaces(self):
                    return list(self.workspaces.keys())

            cls._workspace_manager = WorkspaceManager()
        return cls._workspace_manager
    except Exception as e:
        raise RuntimeError(f"Failed to get workspace manager: {e}") from e

