@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Import yaml locally to avoid global imports
    try:
        import yaml
    except ImportError as exc:
        raise IRValidatorException("PyYAML is required to parse spec content") from exc

    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # Load YAML if provided as a string, otherwise accept a dict directly
    try:
        if isinstance(spec_content, str):
            data = yaml.safe_load(spec_content)
        elif isinstance(spec_content, dict):
            data = spec_content
        else:
            raise IRValidatorException(
                f"Spec content must be a YAML string or a dict, got {type(spec_content).__name__}"
            )
    except Exception as exc:
        raise IRValidatorException(f"Failed to parse spec content: {exc}") from exc

    if not isinstance(data, dict):
        raise IRValidatorException(
            f"Parsed spec content must be a mapping, got {type(data).__name__}"
        )

    # Define required fields for the spec
    required_fields = ["name", "version", "description"]
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(
            f"Missing required fields in spec: {', '.join(missing)}"
        )

    return data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException("yaml_file must be provided")

    try:
        import yaml
    except ImportError as exc:
        raise IRValidatorException("PyYAML is required to parse YAML files") from exc

    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception as exc:
        raise IRValidatorException(f"Error reading YAML file '{yaml_file}': {exc}") from exc

    try:
        data = yaml.safe_load(content)
    except yaml.YAMLError as exc:
        raise IRValidatorException(f"Error parsing YAML file '{yaml_file}': {exc}") from exc

    if data is None:
        raise IRValidatorException(f"YAML file '{yaml_file}' is empty or contains no data")

    # Determine required fields from class attributes
    required_fields = getattr(cls, "REQUIRED_FIELDS", None)
    if required_fields is None:
        required_fields = getattr(cls, "required_fields", None)

    if required_fields:
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required fields in YAML file '{yaml_file}': {', '.join(missing)}"
            )

    return data

