def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        spec = getattr(self, 'spec', None)
        if spec is None:
            return defaults

        # Helper to resolve a single argument spec
        def resolve_arg(name, arg_spec):
            if not isinstance(arg_spec, dict):
                return
            # Try environment variable first
            env_key = arg_spec.get("env")
            if env_key is not None:
                env_val = getattr(self, "env", {}).get(env_key)
                if env_val is not None:
                    defaults[name] = env_val
                    return
            # Try config value next
            cfg_key = arg_spec.get("config")
            if cfg_key is not None:
                cfg_val = getattr(self, "config", {}).get(cfg_key)
                if cfg_val is not None:
                    defaults[name] = cfg_val
                    return
            # Fallback to explicit default
            if "default" in arg_spec:
                defaults[name] = arg_spec["default"]

        if isinstance(spec, dict):
            for name, arg_spec in spec.items():
                resolve_arg(name, arg_spec)
        elif isinstance(spec, (list, tuple)):
            for arg_spec in spec:
                if isinstance(arg_spec, dict):
                    name = arg_spec.get("name")
                    if name:
                        resolve_arg(name, arg_spec)
    except Exception:
        # In case of any unexpected error, return what we have so far
        pass
    return defaults

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Ensure the commands mapping exists
    commands = getattr(self, "commands", None)
    if commands is None:
        raise AttributeError("The object does not have a 'commands' attribute")

    # Retrieve the command
    try:
        command = commands[command_name]
    except KeyError:
        raise KeyError(f"Command '{command_name}' not found")

    # Retrieve the options dictionary from the command
    options = getattr(command, "options", None) or getattr(command, "arguments", None)
    if options is None:
        raise AttributeError(f"Command '{command_name}' does not expose options")

    # Retrieve the option specification
    try:
        spec = options[argument_name]
    except KeyError:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

    return spec

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    try:
        if args is None:
            return []
        # If args is a dictionary, consider keys that start with '_' as silent
        if isinstance(args, dict):
            return [k for k in args if isinstance(k, str) and k.startswith('_')]
        # If args is a list, tuple, or set, filter by underscore prefix
        if isinstance(args, (list, tuple, set)):
            return [arg for arg in args if isinstance(arg, str) and arg.startswith('_')]
        # Attempt to iterate over args if it's an iterable of strings
        try:
            return [arg for arg in args if isinstance(arg, str) and arg.startswith('_')]
        except TypeError:
            # args is not iterable
            return []
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

    # Ensure the class defines required_args
    if not hasattr(self, "required_args"):
        raise AttributeError("The object does not define 'required_args'")

    required = getattr(self, "required_args")
    if not hasattr(required, "__iter__"):
        raise TypeError("'required_args' must be an iterable of argument names")

    # Find any missing required arguments
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

