                    # Simple equality/inequality: key==value or key!=value
                    import re
                    m = re.match(r'^\s*(\w+)\s*(==|!=)\s*(.+)\s*$', cond_item)
                    if m:
                        key, op, val = m.groups()
                        # Strip quotes from val if present
                        if (val.startswith('"') and val.endswith('"')) or \
                           (val.startswith("'") and val.endswith("'")):
                            val = val[1:-1]
                        arg_val = args.get(key)
                        if op == '==':
                            return str(arg_val) == val
                        else:  # op == '!='
                            return str(arg_val) != val
                # Unsupported condition type
                return False

            # If condition is a list/tuple, any True triggers requirement
            if isinstance(cond, (list, tuple)):
                if any(_eval(c) for c in cond):
                    required.append(name)
            else:
                if _eval(cond):
                    required.append(name)
        return required

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # If no arguments provided, nothing to validate
        if args is None:
            return

        # Ensure args is a mapping of argument names to values
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary of argument names to values")

        # Retrieve length specifications from the instance, if any
        # `self.lengths` can be a dict mapping argument names to max lengths
        # `self.max_length` can be a global max length applied to all arguments
        max_lengths = getattr(self, "lengths", None)
        global_max = getattr(self, "max_length", None)

        for name, value in args.items():
            # Skip validation for None values
            if value is None:
                continue

            # Determine the applicable maximum length for this argument
            if isinstance(max_lengths, dict) and name in max_lengths:
                max_len = max_lengths[name]
            else:
                max_len = global_max

            # If no max length is defined, skip this argument
            if max_len is None:
                continue

            # Ensure the max length is a non-negative integer
            if not isinstance(max_len, int) or max_len < 0:
                continue

            # Attempt to get the length of the value
            try:
                length = len(value)
            except TypeError:
                # If the value has no length (e.g., int, float), skip validation
                continue

            # Raise an error if the value exceeds the allowed length
            if length > max_len:
                raise ValueError(
                    f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
                )

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Retrieve the argument definitions; they may be stored in a dict or list
        arg_defs = getattr(self, "arguments", {})
        if not isinstance(arg_defs, dict):
            # If not a dict, try to iterate over it assuming it yields (name, definition) pairs
            try:
                arg_defs = {name: definition for name, definition in arg_defs}
            except Exception:
                # If we cannot interpret the structure, skip validation
                return

        for arg_name, arg_def in arg_defs.items():
            # Extract the list of allowed choices from the definition
            if isinstance(arg_def, dict):
                choices = arg_def.get("choices")
            else:
                choices = getattr(arg_def, "choices", None)

            if not choices:
                # No choices defined for this argument; nothing to validate
                continue

            # Retrieve the value supplied for this argument from the args container
            try:
                # args might be a dict
                value = args[arg_name]
            except (KeyError, TypeError):
                try:
                    # args might be an object with attributes
                    value = getattr(args, arg_name)
                except AttributeError:
                    # Argument not provided; skip validation for this one
                    continue

            # If the value is a collection (e.g., list or tuple), validate each element
            if isinstance(value, (list, tuple)):
                for v in value:
                    if v not in choices:
                        raise ValueError(
                            f"Invalid choice '{v}' for argument '{arg_name}'. "
                            f"Allowed choices: {choices}"
                        )
            else:
                if value not in choices:
                    raise ValueError(
                        f"Invalid choice '{value}' for argument '{arg_name}'. "
                        f"Allowed choices: {choices}"
                    )
        # If all checks pass, return True for clarity
        return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Validate args is not None
    if args is None:
        raise TypeError("args cannot be None")

    # Determine how to iterate over the arguments
    if isinstance(args, dict):
        items = args.items()
    else:
        # Exclude string/bytes from being treated as iterable of values
        if isinstance(args, (str, bytes)):
            raise TypeError("args must be a dict or an iterable of numeric values, not a string")
        try:
            items = [(None, v) for v in args]
        except TypeError:
            raise TypeError("args must be a dict or an iterable of numeric values")

    # Ensure the object has min and max attributes
    if not hasattr(self, "min") or not hasattr(self, "max"):
        raise AttributeError("Object must have 'min' and 'max' attributes for validation")

    min_val = self.min
    max_val = self.max

    # Validate min and max are numeric
    if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
        raise TypeError("'min' and 'max' attributes must be numeric")

    if min_val > max_val:
        raise ValueError("'min' attribute must be less than or equal to 'max' attribute")

    # Validate each argument value
    for key, value in items:
        if not isinstance(value, (int, float)):
            raise TypeError(f"Value for argument '{key}' must be numeric")
        if not (min_val <= value <= max_val):
            raise ValueError(
                f"Value for argument '{key}' ({value}) is out of bounds [{min_val}, {max_val}]"
            )

    return True

