@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        # Validate input dictionary
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        # If no extra vars provided, simply return the original dict
        if extra_vars is None:
            return vars_dict

        # Helper to parse a string value into a more specific type
        def _parse_value(val):
            if isinstance(val, str):
                # Strip surrounding quotes if present
                if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                    val = val[1:-1]
                lower_val = val.lower()
                if lower_val == "true":
                    return True
                if lower_val == "false":
                    return False
                # Try integer conversion
                try:
                    if val.startswith(("0x", "0X")):
                        return int(val, 16)
                    return int(val)
                except ValueError:
                    pass
                # Try float conversion
                try:
                    return float(val)
                except ValueError:
                    pass
            return val

        # Normalize extra_vars to an iterable of key-value pairs
        if isinstance(extra_vars, dict):
            items = extra_vars.items()
        elif isinstance(extra_vars, (list, tuple)):
            items = extra_vars
        elif isinstance(extra_vars, str):
            items = [extra_vars]
        else:
            raise TypeError(f"extra_vars must be a dict, list, tuple, or str, got {type(extra_vars).__name__}")

        for item in items:
            # If item is a tuple or list of two elements, treat as key, value
            if isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
            elif isinstance(item, str):
                # Split on first '='
                if "=" not in item:
                    # Skip items without '='
                    continue
                key, value = item.split("=", 1)
            else:
                # Unsupported item type; skip
                continue

            key = key.strip()
            if not key:
                continue  # Skip empty keys

            # Parse the value
            parsed_value = _parse_value(value.strip())
            vars_dict[key] = parsed_value

        return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Retrieve expected types for this parser if available
        arg_types = getattr(self, "_arg_types", {}).get(parser_name, {})

        def cast_value(val, target_type):
            """Attempt to cast val to target_type, returning original if fails."""
            if val is None:
                return None
            # If already correct type, return as is
            if isinstance(val, target_type):
                return val
            try:
                if target_type is bool:
                    if isinstance(val, str):
                        lowered = val.lower()
                        if lowered in ("true", "1", "yes"):
                            return True
                        if lowered in ("false", "0", "no"):
                            return False
                    # Fallback: use bool constructor
                    return bool(val)
                if target_type is int:
                    return int(val)
                if target_type is float:
                    return float(val)
                if target_type is complex:
                    return complex(val)
                if target_type is list:
                    if isinstance(val, str):
                        return [item.strip() for item in val.split(",") if item.strip()]
                    return list(val)
                if target_type is set:
                    if isinstance(val, str):
                        return {item.strip() for item in val.split(",") if item.strip()}
                    return set(val)
                if target_type is tuple:
                    if isinstance(val, str):
                        return tuple(item.strip() for item in val.split(",") if item.strip())
                    return tuple(val)
                if target_type is dict:
                    # Attempt to parse JSON-like string
                    import json
                    if isinstance(val, str):
                        return json.loads(val)
                    return dict(val)
                # For any other callable type, attempt direct call
                if callable(target_type):
                    return target_type(val)
                # Default: return string
                return str(val)
            except Exception:
                # If casting fails, return original value
                return val

        for key, val in values_dict.items():
            # Determine target type
            target_type = arg_types.get(key)
            if target_type is None:
                # Heuristic casting if no explicit type
                if isinstance(val, str):
                    lowered = val.lower()
                    if lowered in ("true", "false", "1", "0", "yes", "no"):
                        target_type = bool
                    else:
                        # Try numeric
                        try:
                            int(val)
                            target_type = int
                        except ValueError:
                            try:
                                float(val)
                                target_type = float
                            except ValueError:
                                # Try list
                                if "," in val:
                                    target_type = list
                                else:
                                    target_type = str
                else:
                    target_type = type(val)
            # Cast and update
            values_dict[key] = cast_value(val, target_type)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Validate input
    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    # Find the spec file (JSON or YAML)
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break
    if spec_path is None:
        raise FileNotFoundError("No plugin spec file found in directory")

    # Load the spec
    try:
        if spec_path.endswith(".json"):
            with open(spec_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        else:
            try:
                import yaml
            except ImportError as exc:
                raise ImportError("yaml module not available to parse YAML spec") from exc
            with open(spec_path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("Plugin spec root must be a dictionary")

    # Flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        # Use a standard environment variable name for the config path
        env_var = "CONFIG_PATH"
        if os.getenv(env_var) is None:
            # Default to a config.yaml file in the current working directory
            default_path = os.path.join(os.getcwd(), "config.yaml")
            os.environ[env_var] = default_path
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError for clarity
        raise RuntimeError(f"Failed to set {env_var}: {exc}") from exc
